import * as React from "react"
import { Pressable, Text, type GestureResponderEvent } from "react-native"
import type { UnistylesVariants } from "react-native-unistyles"
import { buttonStyles, useButtonVariants } from "../../theme/variants/button"
import { layoutToStyle, type LayoutProps } from "./layout"

export type ButtonProps = {
  children?: React.ReactNode
  layout?: LayoutProps
  onPress?: (event: GestureResponderEvent) => void
} & UnistylesVariants<typeof buttonStyles>

export function Button({
  children,
  variant,
  size,
  disabled,
  layout,
  onPress,
}: ButtonProps) {
  useButtonVariants({
    variant,
    size,
    disabled,
  })

  return (
    <Pressable
      accessibilityRole="button"
      disabled={Boolean(disabled)}
      onPress={onPress}
      style={[buttonStyles.root, layoutToStyle(layout)]}
    >
      <Text style={buttonStyles.label}>{children}</Text>
    </Pressable>
  )
}

import type { ViewStyle } from "react-native"

export type LayoutProps = {
  margin?: ViewStyle["margin"]
  width?: ViewStyle["width"]
  maxWidth?: ViewStyle["maxWidth"]
}

export function layoutToStyle(layout?: LayoutProps): ViewStyle | undefined {
  if (!layout) return undefined
  const style: ViewStyle = {}
  if (layout.margin !== undefined) style.margin = layout.margin
  if (layout.width !== undefined) style.width = layout.width
  if (layout.maxWidth !== undefined) style.maxWidth = layout.maxWidth
  return Object.keys(style).length > 0 ? style : undefined
}

export type NativeTheme = {
  colors: {
    bg: {
      surface: string
      accent: string
      muted: string
    }
    fg: {
      default: string
      muted: string
      onAccent: string
    }
    border: {
      default: string
      focus: string
    }
  }
  space: {
    control: {
      px: number
      py: number
      gap: number
    }
  }
  radius: {
    control: number
  }
  typography: {
    label: {
      fontSize: number
    }
  }
  opacity: {
    disabled: number
  }
}

/** Lib playground demo only. Client apps must supply their own theme values. */
export const defaultDemoTheme = {
  colors: {
    bg: {
      surface: "#ffffff",
      accent: "#18181b",
      muted: "#f4f4f5",
    },
    fg: {
      default: "#18181b",
      muted: "#71717a",
      onAccent: "#fafafa",
    },
    border: {
      default: "#e4e4e7",
      focus: "#2563eb",
    },
  },
  space: {
    control: {
      px: 12,
      py: 8,
      gap: 8,
    },
  },
  radius: {
    control: 8,
  },
  typography: {
    label: {
      fontSize: 14,
    },
  },
  opacity: {
    disabled: 0.5,
  },
} satisfies NativeTheme
